import React, { useState, useEffect } from "react";

const Test = () => {
    const [topic, setTopic] = useState("");
    const [topics, setTopics] = useState([]);
    const [questions, setQuestions] = useState([]);
    const [answers, setAnswers] = useState({});
    const [loading, setLoading] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [score, setScore] = useState(0);

    useEffect(() => {
        const savedTopics = JSON.parse(localStorage.getItem("chatTopics")) || [];
        setTopics(savedTopics);
    }, []);

    const fetchAIQuestions = async () => {
        if (!topic) return;
        setLoading(true);
        setQuestions([]);
        setAnswers({});
        setSubmitted(false);
        setScore(0);

        try {
            const response = await fetch("http://localhost:5000/generate-questions", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ topic, numQuestions: 10 }),
            });

            const data = await response.json();
            if (data.questions && data.questions.length > 0) {
                setQuestions(data.questions);
            }
        } catch (error) {
            console.error("Error fetching AI questions:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleAnswerSelect = (questionIndex, selectedOption) => {
        setAnswers((prevAnswers) => ({
            ...prevAnswers,
            [questionIndex]: selectedOption,
        }));
    };

    const handleSubmit = () => {
        let newScore = 0;
        questions.forEach((q, index) => {
            if (answers[index] === q.correctAnswer) {
                newScore++;
            }
        });
        setScore(newScore);
        setSubmitted(true);
    };

    return (
        <div style={styles.container}>
            <div style={styles.testBox}>
                <h2 style={styles.heading}>📝 AI Generated Quiz</h2>

                <div style={styles.topicSelection}>
                    <select value={topic} onChange={(e) => setTopic(e.target.value)} style={styles.select}>
                        <option value="">Select a Topic</option>
                        {topics.length > 0 ? (
                            topics.map((t, index) => <option key={index} value={t}>{t}</option>)
                        ) : (
                            <option disabled>No topics found</option>
                        )}
                    </select>

                    <button onClick={fetchAIQuestions} disabled={loading || !topic} style={styles.generateButton}>
                        {loading ? "Generating..." : "Generate Questions"}
                    </button>
                </div>

                {questions.length > 0 && (
                    <div style={styles.questionContainer}>
                        <h3>🧐 Questions</h3>
                        {questions.map((q, index) => (
                            <div key={index} style={styles.questionBox}>
                                <strong>{index + 1}. {q.question}</strong>
                                <div>
                                    {Object.entries(q.options).map(([key, option]) => (
                                        <label key={key} style={styles.optionLabel}>
                                            <input
                                                type="radio"
                                                name={`question-${index}`}
                                                value={key}
                                                checked={answers[index] === key}
                                                onChange={() => handleAnswerSelect(index, key)}
                                                disabled={submitted}
                                                style={styles.radioInput}
                                            />
                                            {option}
                                        </label>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {questions.length > 0 && !submitted && (
                    <button onClick={handleSubmit} style={styles.submitButton}>
                        Submit Answers
                    </button>
                )}

                {submitted && (
                    <div style={styles.scorecard}>
                        <h3>🎯 Scorecard</h3>
                        <p><strong>Your Score: {score} / {questions.length}</strong></p>
                        <h4>✅ Correct Answers:</h4>
                        <ul>
                            {questions.map((q, index) => (
                                <li key={index}>
                                    {q.question} - <strong>{q.options[q.correctAnswer]}</strong>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    container: {
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#007BFF",
        padding: "20px",
    },
    testBox: {
        backgroundColor: "#fff",
        color: "#333",
        padding: "20px",
        borderRadius: "10px",
        boxShadow: "0px 4px 8px rgba(0, 0, 0, 0.2)",
        maxWidth: "600px",
        width: "100%",
    },
    heading: {
        textAlign: "center",
        fontSize: "22px",
        fontWeight: "bold",
        marginBottom: "15px",
    },
    topicSelection: {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        marginBottom: "15px",
    },
    select: {
        flex: 1,
        padding: "8px",
        borderRadius: "5px",
        border: "1px solid #ccc",
        fontSize: "16px",
    },
    generateButton: {
        marginLeft: "10px",
        padding: "8px 15px",
        backgroundColor: "#28a745",
        color: "#fff",
        border: "none",
        borderRadius: "5px",
        cursor: "pointer",
        fontSize: "16px",
    },
    questionContainer: {
        maxHeight: "350px",
        overflowY: "auto",
        border: "1px solid #ccc",
        padding: "10px",
        borderRadius: "5px",
        marginBottom: "15px",
        backgroundColor: "#f9f9f9",
    },
    questionBox: {
        marginBottom: "10px",
        padding: "10px",
        borderBottom: "1px solid #ddd",
    },
    optionLabel: {
        display: "block",
        padding: "5px 0",
        fontSize: "16px",
        cursor: "pointer",
    },
    radioInput: {
        marginRight: "5px",
    },
    submitButton: {
        display: "block",
        width: "100%",
        padding: "10px",
        backgroundColor: "#007BFF",
        color: "#fff",
        border: "none",
        borderRadius: "5px",
        cursor: "pointer",
        fontSize: "16px",
    },
    scorecard: {
        marginTop: "20px",
        padding: "15px",
        borderRadius: "5px",
        backgroundColor: "#f8f9fa",
        border: "1px solid #ccc",
    },
};

export default Test;
